#
# Emit tables.go for package qr from pyqrcode's tables, so the encoder
# and its test oracle share one source of truth.
#
#   $BBQR/python/ENV/bin/python gen_tables.py > ../tables.go && gofmt -w ../tables.go
#
from pyqrcode import tables

LEVELS = 'LMQH'

print('''// Code generated by testdata/gen_tables.py from pyqrcode's tables; DO NOT EDIT.

package qr

// ecBlocks[v-1][level] lays out the error correction of version v: the
// number of error correction codewords per block, then the block count
// and data codewords per block of the first group, then of the second.
var ecBlocks = [MaxVersion][4]struct{ ec, n1, d1, n2, d2 int }{''')
for v in range(1, 41):
    row = []
    for lvl in LEVELS:
        ec, n1, d1, n2, d2 = tables.eccwbi[v][lvl]
        assert (n1 * d1 + n2 * d2) * 8 == tables.data_capacity[v][lvl][0]
        row.append('{%d, %d, %d, %d, %d}' % (ec, n1, d1, n2, d2))
    print('\t{%s}, // %d' % (', '.join(row), v))
print('}')

print('''
// alignPositions[v-1] holds the row and column coordinates of the
// alignment pattern centres of version v.
var alignPositions = [MaxVersion][]int{''')
for v in range(1, 41):
    pos = tables.position_adjustment[v] or []
    print('\t{%s},' % ', '.join(str(p) for p in pos))
print('}')
